/** Immutable protein manifests and producer-verified primary scopes; accession syntax is never guessed. */
final class StudyProteinInputs {
    private StudyProteinInputs() { }
    static final Set<String> MODEL_FILES=Set.of("file","pae","pae_index","residue_map","confidence_file");
    record Loaded(List<Map<String,Object>> targets,Map<String,String> sequences,List<Object> sources) { }
    static Map<String,Object> manifest(Path root,Map<String,Object> p)throws IOException {
        if(!p.containsKey("manifest"))return Map.of();Path file=root.resolve(text(p.get("manifest")));if(!Files.isRegularFile(file))throw new IllegalArgumentException("Supply the registered protein manifest");if(Files.size(file)>2097152L)throw new IllegalArgumentException("Protein manifest exceeds the 2-MiB metadata bound");var doc=StudyYaml.loadArtifact(file);unknown(doc,Set.of("schema_version","targets","provenance"),"protein manifest");if(doc.containsKey("schema_version")&&!Integer.valueOf(1).equals(doc.get("schema_version")))throw new IllegalArgumentException("Unsupported protein manifest schema_version");if(!(doc.get("targets") instanceof List<?>))throw new IllegalArgumentException("Protein manifest requires a targets list");return doc;
    }
    static Loaded load(Context c,Map<String,Object> p)throws IOException {
        var sources=new ArrayList<Object>();var sequences=new LinkedHashMap<String,String>();var targets=new ArrayList<Map<String,Object>>();Path inputs=c.outputDirectory().resolve("protein-inputs");Files.createDirectories(inputs);
        if(p.containsKey("sequences")){Path file=c.project().resolve(text(p.get("sequences")));if(!Files.isRegularFile(file))throw new IllegalArgumentException("Supply the registered protein FASTA");if(Files.size(file)>((Number)p.get("max_file_bytes")).longValue())throw new IllegalArgumentException("Protein FASTA exceeds its byte bound");Path copy=snapshot(file,inputs.resolve("sequences.fasta"));sequences.putAll(ProteinStructure.fasta(Files.readString(copy),10000,((Number)p.get("max_residues")).intValue()));sources.add(Map.of("kind","target_sequences","source",p.get("sequences"),"sha256",FollowupSupport.hash(copy),"normalization","Uppercase amino-acid letters without whitespace; no stop stripping or wildcard matching"));}
        if(p.containsKey("manifest")){if(!"explicit".equals(p.get("scope")))throw new IllegalArgumentException("A protein manifest defines an explicit target scope; use scope: explicit and retain the source selection protocol in provenance");var doc=manifest(c.project(),p);Path copy=snapshot(c.project().resolve(text(p.get("manifest"))),inputs.resolve("protein-manifest.yaml"));sources.add(Map.of("kind","target_manifest","source",p.get("manifest"),"sha256",FollowupSupport.hash(copy),"provenance",doc.getOrDefault("provenance",Map.of())));for(Object raw:list(doc.get("targets")))targets.add(target(map(raw)));}
        else if("explicit".equals(p.get("scope")))throw new IllegalArgumentException("Explicit protein scope needs a manifest, including sequence/assay mappings and supplied models where available");
        else targets.addAll(automatic(c,p,sources));
        int fallback=taxon(c,p);var identities=new LinkedHashSet<String>();for(var target:targets){if(!target.containsKey("taxon_id")&&fallback>0)target.put("taxon_id",fallback);String identity=text(target.get("feature_id"))+"\u001f"+text(target.get("protein_id"))+"\u001f"+text(target.get("dataset_id"))+"\u001f"+text(target.get("sequence_id"));if(!identities.add(identity))throw new IllegalArgumentException("Duplicate scoped protein target; combine its models explicitly rather than count it twice");}
        return new Loaded(List.copyOf(targets),Map.copyOf(sequences),List.copyOf(sources));
    }
    static Map<String,Object> target(Map<String,Object> raw){var t=new LinkedHashMap<String,Object>(raw);unknown(t,Set.of("feature_id","protein_id","sequence_id","sequence_version","isoform_id","taxon_id","dataset_id","transcript_id","assay_mapping","models","regions","variants","partners","complex_justification","prediction_inputs","provenance"),"protein target");for(String key:List.of("feature_id","protein_id"))if(!(t.get(key) instanceof String s)||s.isBlank()||s.length()>500)throw new IllegalArgumentException("Protein target requires a nonblank bounded "+key);
        if(t.containsKey("taxon_id"))positive(t.get("taxon_id"),"taxon_id");for(String key:List.of("sequence_id","sequence_version","isoform_id","dataset_id","transcript_id","complex_justification"))if(t.containsKey(key)&&(!(t.get(key) instanceof String s)||s.isBlank()))throw new IllegalArgumentException("Protein "+key+" must be nonblank text");
        for(String field:List.of("models","regions","variants","partners"))if(t.containsKey(field)&&!(t.get(field) instanceof List<?>))throw new IllegalArgumentException("Protein "+field+" must be a list");if(t.containsKey("assay_mapping")&&!(t.get("assay_mapping") instanceof Map<?,?>))throw new IllegalArgumentException("Protein assay_mapping must be an object");
        var mapping=map(t.get("assay_mapping"));unknown(mapping,Set.of("status","source","peptides","limitations"),"assay mapping");if(mapping.containsKey("status")&&!Set.of("supplied_sequence","protein_group","gene_level_only","isoform_unknown","accession_declared","unknown").contains(mapping.get("status")))throw new IllegalArgumentException("Invalid assay_mapping.status");if(mapping.containsKey("peptides")&&!(mapping.get("peptides") instanceof List<?>))throw new IllegalArgumentException("assay_mapping.peptides must be a list");if(mapping.containsKey("limitations")&&!(mapping.get("limitations") instanceof String)&&!(mapping.get("limitations") instanceof List<?> values&&values.stream().allMatch(v->v instanceof String)))throw new IllegalArgumentException("assay_mapping.limitations must be text or a list of text");for(Object peptide:list(mapping.get("peptides")))ProteinStructure.sequence(text(peptide));t.put("assay_mapping",mapping);
        var models=new ArrayList<Object>();for(Object model:list(t.get("models")))models.add(model(map(model)));t.put("models",models);var modelIds=new LinkedHashSet<String>();for(Object model:models)if(!modelIds.add(text(map(model).get("id"))))throw new IllegalArgumentException("Duplicate model ID within protein target");
        var regions=new LinkedHashSet<String>();for(Object rawRegion:list(t.get("regions"))){var r=map(rawRegion);unknown(r,Set.of("id","start","end"),"protein region");String id=text(r.get("id"));if(id.isBlank()||!regions.add(id))throw new IllegalArgumentException("Protein regions need unique IDs");int start=positive(r.get("start"),"region start"),end=positive(r.get("end"),"region end");if(end<start)throw new IllegalArgumentException("Reversed protein region");}
        var variants=new LinkedHashSet<String>();for(Object rawVariant:list(t.get("variants"))){var v=map(rawVariant);unknown(v,Set.of("id","position","ref","alt","transcript_id","genomic_variant","mapping_provenance"),"protein variant");if(text(v.get("id")).isBlank()||!variants.add(text(v.get("id"))))throw new IllegalArgumentException("Protein variants need unique IDs");positive(v.get("position"),"protein variant position");if(ProteinStructure.sequence(text(v.get("ref"))).length()!=1||ProteinStructure.sequence(text(v.get("alt"))).length()!=1)throw new IllegalArgumentException("Residue context requires single-amino-acid REF/ALT; indels need an appropriate sequence model");}
        var partners=new LinkedHashSet<String>();for(Object rawPartner:list(t.get("partners"))){var partner=map(rawPartner);unknown(partner,Set.of("chain","sequence_id"),"protein partner");if(text(partner.get("chain")).isBlank()||text(partner.get("sequence_id")).isBlank()||!partners.add(text(partner.get("chain"))))throw new IllegalArgumentException("Partners need unique chain IDs and exact sequence IDs");}if(!partners.isEmpty()&&text(t.get("complex_justification")).isBlank())throw new IllegalArgumentException("A protein complex requires complex_justification");return t;
    }
    static Map<String,Object> model(Map<String,Object> raw){var m=new LinkedHashMap<String,Object>(raw);unknown(m,Set.of("id","file","format","chain","model_number","sequence_start","model_sequence_id","residue_map","confidence_source","confidence_file","confidence_provenance","pae","pae_index","pae_provenance","structure_kind","method","model_version","source","seed","ranking_metric","ranking_value","source_sequence_sha256","provenance"),"protein model");if(text(m.get("id")).isBlank())throw new IllegalArgumentException("Protein models need an ID");for(String key:MODEL_FILES)if(m.containsKey(key)&&text(m.get(key)).isBlank())throw new IllegalArgumentException("Empty protein model file field: "+key);
        m.putIfAbsent("format","auto");m.putIfAbsent("model_number",1);m.putIfAbsent("sequence_start",1);m.putIfAbsent("confidence_source","none");m.putIfAbsent("structure_kind","unknown");positive(m.get("model_number"),"model_number");positive(m.get("sequence_start"),"sequence_start");if(!Set.of("auto","pdb","cif","mmcif").contains(m.get("format")))throw new IllegalArgumentException("Unsupported protein model format");if(!Set.of("none","b_factor_plddt","residue_file").contains(m.get("confidence_source")))throw new IllegalArgumentException("Unsupported protein confidence source");if(!Set.of("unknown","experimental","alphafold_prediction","other_prediction").contains(m.get("structure_kind")))throw new IllegalArgumentException("Invalid structure_kind");
        if(!"none".equals(m.get("confidence_source"))&&text(m.get("confidence_provenance")).isBlank())throw new IllegalArgumentException("Declared pLDDT needs confidence_provenance; B-factors alone do not identify this metric");if("b_factor_plddt".equals(m.get("confidence_source"))&&"experimental".equals(m.get("structure_kind")))throw new IllegalArgumentException("Experimental B-factors cannot be interpreted as AlphaFold pLDDT");if("residue_file".equals(m.get("confidence_source"))&&!m.containsKey("confidence_file"))throw new IllegalArgumentException("Residue pLDDT needs confidence_file");return m;
    }
    private static List<Map<String,Object>> automatic(Context c,Map<String,Object> p,List<Object> sources)throws IOException {
        var primary=StudyPrimaryResults.official(c);
        if(primary==null)throw new IllegalArgumentException("Protein scope needs a completed primary association/meta-analysis or an explicit target manifest");
        Path pooled=primary.source().dataset().isEmpty()?primary.source().path():null;
        var tables=Map.of(primary.source().dataset(),primary.source().path());
        sources.add(Map.of("kind","primary_selection","selection",primary.receipt()));
        var datasets=StudyBioinformatics.datasets(c);Set<String> selected=new LinkedHashSet<>(list(c.operation().get("datasets")).stream().map(StudyPublicEvidence::text).toList());var annotations=new LinkedHashMap<String,List<Map<String,Object>>>();boolean direct=!selected.isEmpty()&&datasets.stream().filter(d->selected.contains(text(d.get("id")))).allMatch(d->Set.of("uniprot","uniprot_accession","uniprot_isoform").contains(text(d.get("feature_id_type"))));
        if(!direct&&pooled!=null&&Files.isRegularFile(pooled.getParent().resolve("supplied-analysis.yaml"))){var scope=map(StudyYaml.loadArtifact(pooled.getParent().resolve("supplied-analysis.yaml")).get("scope"));direct=Set.of("uniprot","uniprot_accession","uniprot_isoform").contains(text(scope.get("feature_id_type")));}
        for(var dataset:datasets)if(selected.contains(text(dataset.get("id")))&&map(dataset.get("files")).containsKey("feature_annotation")){Path file=c.project().resolve(text(map(dataset.get("files")).get("feature_annotation")));if(!Files.isRegularFile(file))continue;if(Files.size(file)>((Number)p.get("max_file_bytes")).longValue())throw new IllegalArgumentException("Protein annotation exceeds byte bound");Path annotationCopy=snapshot(file,c.outputDirectory().resolve("protein-inputs").resolve("annotation-"+dataset.get("id")+(file.toString().endsWith(".csv")?".csv":".tsv")));var table=DelimitedData.readResult(annotationCopy);String protein=table.header().contains("protein_id")?"protein_id":table.header().contains("uniprot_accession")?"uniprot_accession":"";if(protein.isEmpty())continue;String hash=FollowupSupport.hash(file);for(String[] row:table.rows()){var a=new LinkedHashMap<String,Object>();a.put("protein_id",row[table.column(protein)]);for(String field:List.of("sequence_id","sequence_version","isoform_id"))if(table.header().contains(field)&&!row[table.column(field)].isBlank())a.put(field,row[table.column(field)]);if(table.header().contains("taxon_id")&&!row[table.column("taxon_id")].isBlank())a.put("taxon_id",Integer.parseInt(row[table.column("taxon_id")]));a.put("assay_mapping",Map.of("status","accession_declared","source","Dataset "+dataset.get("id")+" feature annotation; sequence/assay equivalence requires source appraisal"));annotations.computeIfAbsent(dataset.get("id")+"\u001f"+row[table.column("feature_id")],key->new ArrayList<>()).add(a);}if(!hash.equals(FollowupSupport.hash(file)))throw new IOException("Protein annotation changed while reading");sources.add(Map.of("kind","protein_mapping","dataset_id",dataset.get("id"),"source",file.toString(),"sha256",hash));}
        var targets=new ArrayList<Map<String,Object>>();for(var entry:tables.entrySet()){var table=primary.table();var pValues=primary.probabilities();var retained=table.rows().stream().filter(row->pValues.containsKey(row[table.column("feature_id")])).toList();
            var adjusted=primary.adjusted();sources.add(Map.of("kind","primary_results","dataset_id",entry.getKey(),"source",c.project().relativize(entry.getValue()).toString(),"sha256",FollowupSupport.hash(entry.getValue()),"eligible_statistical_rows",pValues.size(),"scope",p.get("scope")));
            for(String[] row:retained){String feature=row[table.column("feature_id")];double q=adjusted.getOrDefault(feature,Double.NaN);if("primary_significant".equals(p.get("scope"))&&!(q<((Number)p.get("fdr")).doubleValue()))continue;boolean directEntry=entry.getKey().isEmpty()?direct:datasets.stream().filter(d->entry.getKey().equals(d.get("id"))).anyMatch(d->Set.of("uniprot","uniprot_accession","uniprot_isoform").contains(text(d.get("feature_id_type"))));var candidates=entry.getKey().isEmpty()?annotations.entrySet().stream().filter(e->e.getKey().endsWith("\u001f"+feature)).flatMap(e->e.getValue().stream()).toList():annotations.getOrDefault(entry.getKey()+"\u001f"+feature,List.of());if(candidates.isEmpty()){var t=new LinkedHashMap<String,Object>();t.put("feature_id",feature);t.put("protein_id",directEntry?feature:"");t.put("dataset_id",entry.getKey());t.put("assay_mapping",Map.of("status",directEntry?"accession_declared":"gene_level_only","source","Primary feature namespace; no exact assayed sequence was supplied"));targets.add(t);}else{var distinct=new LinkedHashSet<String>();for(var candidate:candidates){if(!distinct.add(text(candidate.get("protein_id"))+"\u001f"+text(candidate.get("sequence_id"))))continue;var t=new LinkedHashMap<>(candidate);t.put("feature_id",feature);t.put("dataset_id",entry.getKey());if(candidates.stream().map(a->text(a.get("protein_id"))).distinct().count()>1)t.put("assay_mapping",Map.of("status","protein_group","source","Multiple declared protein candidates; all candidates retained without choosing a canonical counterpart"));targets.add(t);}}}
        }return targets;
    }
    static int taxon(Context c,Map<String,Object> p){if(p.containsKey("taxon_id"))return ((Number)p.get("taxon_id")).intValue();String species=StudyBioinformatics.species(c);try{return Integer.parseInt(species);}catch(NumberFormatException unknown){return 0;}}
    static int positive(Object raw,String label){if(!(raw instanceof Number n)||!Double.isFinite(n.doubleValue())||n.doubleValue()!=n.intValue()||n.intValue()<1)throw new IllegalArgumentException(label+" must be a positive integer");return n.intValue();}
    static Path snapshot(Path source,Path target)throws IOException{String hash=FollowupSupport.hash(source);Files.createDirectories(target.getParent());Files.copy(source,target);if(!hash.equals(FollowupSupport.hash(source))||!hash.equals(FollowupSupport.hash(target)))throw new IOException("Protein input changed while taking its immutable snapshot");return target;}
    static void unknown(Map<String,Object> value,Set<String> fields,String label){for(String key:value.keySet())if(!fields.contains(key))throw new IllegalArgumentException("Unknown "+label+" field: "+key);}
    private static double probability(String value){try{double number=Double.parseDouble(value);return Double.isFinite(number)&&number>=0&&number<=1?number:Double.NaN;}catch(NumberFormatException invalid){return Double.NaN;}}
}
